// HD texture pack: high-resolution colour / normal / roughness maps generated by tools/gen_textures.py (JPEGs in
// public/tex, turned into data-URL scripts by the build). Loaded at a resolution that matches the graphics quality;
// if anything is missing the game keeps its built-in procedural textures.
import * as THREE from 'three';

const PACK = {
  cinder: ['c', 'n', 'r'], concrete: ['c', 'n', 'r'], yard: ['c', 'n', 'r'], grass: ['c', 'n'], asphalt: ['c', 'n', 'r'],
  shingles: ['c', 'n'], metal: ['c', 'n', 'r'], pine: ['c', 'n'], floor: ['c', 'n'], dust: ['c', 'n'],
};
const KEY = { c: 'map', n: 'normalMap', r: 'roughnessMap' };

// textures ship as tex/<name>.js scripts that store a data URL in window.__TEX (see scripts/build.mjs)
function loadScript(url) {
  return new Promise((res, rej) => {
    const s = document.createElement('script');
    s.onload = () => { s.remove(); res(); };
    s.onerror = () => { s.remove(); rej(new Error('missing ' + url)); };
    s.src = url;
    document.head.appendChild(s);
  });
}
async function loadImage(key) {
  await loadScript(`tex/${key}.js`);
  const data = window.__TEX && window.__TEX[key];
  if (!data) throw new Error('no data ' + key);
  const img = new Image();
  img.src = data;
  await img.decode();
  delete window.__TEX[key]; // free the big string once decoded
  return img;
}

// a canvas readback throws if the browser treats local files as cross-origin (WebGL would refuse them too)
function usable(img) {
  try {
    const c = document.createElement('canvas'); c.width = c.height = 2;
    const x = c.getContext('2d'); x.drawImage(img, 0, 0, 2, 2); x.getImageData(0, 0, 1, 1);
    return true;
  } catch (e) { return false; }
}

export async function loadTexturePack(quality, anisotropy, onProgress) {
  const size = quality === 'low' ? 512 : quality === 'medium' ? 1024 : 2048;
  const jobs = [];
  for (const [name, maps] of Object.entries(PACK)) for (const m of maps) jobs.push([name, m]);
  const out = {};
  let done = 0;
  for (const [name, m] of jobs) {
    let img;
    try { img = await loadImage(`${name}_${m}`); } catch (e) { return null; }
    if (done === 0 && !usable(img)) return null;
    let src = img;
    if (img.width > size) {
      const c = document.createElement('canvas'); c.width = c.height = size;
      const x = c.getContext('2d'); x.imageSmoothingQuality = 'high'; x.drawImage(img, 0, 0, size, size);
      src = c;
    }
    const t = src === img ? new THREE.Texture(img) : new THREE.CanvasTexture(src);
    t.wrapS = t.wrapT = THREE.RepeatWrapping;
    t.colorSpace = m === 'c' ? THREE.SRGBColorSpace : THREE.NoColorSpace;
    t.anisotropy = anisotropy;
    t.generateMipmaps = true; t.minFilter = THREE.LinearMipmapLinearFilter;
    t.needsUpdate = true;
    (out[name] = out[name] || {})[KEY[m]] = t;
    done++;
    if (onProgress) onProgress(done / jobs.length);
    // let the loading screen breathe on slow phones
    if (done % 4 === 0) await new Promise((r) => setTimeout(r, 0));
  }
  return out;
}
